code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    crosses = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r - 1][c] == grid[r + 1][c] ==
                grid[r][c - 1] == grid[r][c + 1] == 3 and grid[r][c] != 3):
                crosses.append((r, c, grid[r][c]))
    hollow_cols = {c for r, c, color in crosses if color == 0}
    sources = [(r, c, color) for r, c, color in crosses if color not in (0, 3)]
    horizontal = {}
    vertical = {}
    for r, c, color in sources:
        own_arms = {(r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)}
        horizontal[(r, c)] = color
        vertical[(r, c)] = color
        for dr, dc, target in ((-1, 0, vertical), (1, 0, vertical),
                               (0, -1, horizontal), (0, 1, horizontal)):
            rr, cc = r + dr, c + dc
            while 0 <= rr < h and 0 <= cc < w:
                if grid[rr][cc] == 3 and (rr, cc) not in own_arms:
                    break
                if grid[rr][cc] != 3:
                    target[(rr, cc)] = color
                rr += dr
                cc += dc
    # Horizontal rays are drawn first; vertical rays overwrite them at crossings.
    for (r, c), color in horizontal.items():
        if grid[r][c] != 3:
            out[r][c] = color
    for (r, c), color in vertical.items():
        if grid[r][c] != 3:
            out[r][c] = color
    # An empty-centered cross leaves its column uncolored in horizontal rays.
    for r in range(h):
        for c in hollow_cols:
            if grid[r][c] == 0:
                out[r][c] = 0
    return out
'''
